/* global Word */
/**
 * The checklist items that depend on how text is *formatted*, not what it says:
 * フォント関係（日英不一致・ギリシャ文字）, 物理量のイタリック, 化合物番号と図表番号の太字.
 *
 * Each check picks candidate spans with a pure probe from `src/core/probes.ts`,
 * resolves them to Word ranges, then reads the font. Findings are built with the
 * same `Finding` shape as the text rules so the task pane treats them alike.
 */
import {
  SYMBOL_FONT,
  isJapaneseFontName,
  latinFontMismatch,
  preferredLatinFont,
  symbolKeysFor,
} from "../core/fonts.ts";
import {
  captionNumberProbes,
  compoundNumberProbes,
  greekProbes,
  intextRefProbes,
  journalNameProbes,
  nmrNuclideProbes,
  quantityProbes,
  symbolGreekProbes,
  volumeNumberProbes,
  type Probe,
} from "../core/probes.ts";
import { digitRunFor, japaneseLatinSpacingRule } from "../core/rules/format.ts";
import { parseCaption } from "../core/rules/figure.ts";
import type { Category, Finding } from "../core/types.ts";
import { EXACT, occurrenceIndex, searchTermFor } from "./locate.ts";

const SPACING_RULE_ID = japaneseLatinSpacingRule.id;

/** A formatting check: which spans to look at, and what is wrong with them. */
interface FormatCheck {
  readonly id: string;
  readonly title: string;
  readonly category: Category;
  readonly probe: (text: string) => Probe[];
  /** Fields to load from the range's font. */
  readonly load: string;
  /** Returns a message when the formatting is wrong, or null when it is fine. */
  readonly verdict: (font: Word.Font, probe: Probe) => string | null;
  /** Formatting applied by the "修正" button. */
  readonly fix?: (font: Word.Font, latinFont: string) => void;
  /** Text the "修正" button writes first, when the fix is not formatting alone. */
  readonly replacement?: (probe: Probe) => string | undefined;
  /**
   * A check that covers this one entirely. While it is switched on, this check
   * stays quiet, so the same span is not reported twice with different advice.
   */
  readonly supersededBy?: string;
  readonly severity: Finding["severity"];
}

const CHECKS: readonly FormatCheck[] = [
  {
    id: "greek-symbol-font",
    category: "format",
    title: "ギリシャ文字は Symbol フォント",
    probe: symbolGreekProbes,
    load: "name",
    severity: "confirm",
    // Every Unicode Greek character is wrong under this convention, whatever
    // font carries it, so the font is read only to describe the current state.
    verdict: (font, probe) =>
      font.name && !isJapaneseFontName(font.name)
        ? `${probe.reason}（現在: ${font.name}）`
        : probe.reason,
    replacement: (probe) => symbolKeysFor(probe.text) ?? undefined,
    fix: (font) => {
      font.name = SYMBOL_FONT;
    },
  },
  {
    id: "greek-font",
    category: "format",
    title: "ギリシャ文字に日本語フォント",
    probe: greekProbes,
    load: "name",
    severity: "fix",
    // 「Symbol フォント」 replaces the character outright, which fixes the font
    // question too; running both would put two contradictory findings on one π.
    supersededBy: "greek-symbol-font",
    verdict: (font, probe) =>
      isJapaneseFontName(font.name)
        ? `${probe.reason}（現在: ${font.name}）。欧文フォントに変更してください。`
        : null,
    fix: (font, latinFont) => {
      font.name = latinFont;
    },
  },
  {
    id: "nmr-superscript",
    category: "format",
    title: "核種の質量数は上付き",
    probe: nmrNuclideProbes,
    load: "superscript",
    severity: "fix",
    verdict: (font, probe) => (font.superscript ? null : probe.reason),
    fix: (font) => {
      font.superscript = true;
    },
  },
  {
    id: "quantity-italic",
    category: "format",
    title: "物理量はイタリック",
    probe: quantityProbes,
    load: "italic",
    severity: "fix",
    verdict: (font, probe) => (font.italic ? null : probe.reason),
    fix: (font) => {
      font.italic = true;
    },
  },
  {
    id: "caption-number-bold",
    category: "figure",
    title: "キャプションの図表番号は太字",
    probe: captionNumberProbes,
    load: "bold",
    severity: "fix",
    verdict: (font, probe) => (font.bold ? null : probe.reason),
    fix: (font) => {
      font.bold = true;
    },
  },
  {
    id: "intext-ref-not-bold",
    category: "figure",
    title: "本文中の図表番号は太字にしない",
    probe: intextRefProbes,
    load: "bold",
    severity: "fix",
    verdict: (font, probe) => (font.bold ? probe.reason : null),
    fix: (font) => {
      font.bold = false;
    },
  },
  {
    id: "compound-number-bold",
    category: "figure",
    title: "化合物番号は太字",
    probe: compoundNumberProbes,
    load: "bold",
    severity: "confirm",
    verdict: (font, probe) => (font.bold ? null : probe.reason),
    fix: (font) => {
      font.bold = true;
    },
  },
  {
    id: "reference-journal-italic",
    category: "reference",
    title: "引用文献の誌名は斜体",
    probe: journalNameProbes,
    load: "italic",
    // Which token is emphasised is the journal's house style, so this is raised
    // for confirmation even though the fix itself is unambiguous.
    severity: "confirm",
    verdict: (font, probe) => (font.italic ? null : probe.reason),
    fix: (font) => {
      font.italic = true;
    },
  },
  {
    id: "reference-volume-italic",
    category: "reference",
    title: "引用文献の巻は斜体",
    probe: volumeNumberProbes,
    load: "italic",
    severity: "confirm",
    verdict: (font, probe) => (font.italic ? null : probe.reason),
    fix: (font) => {
      font.italic = true;
    },
  },
];

// --- 段落そのものの書式 ----------------------------------------------------
//
// 「キャプションは中央揃えではなく図の左端に合わせる」 is about the paragraph, not a
// span inside it, so it cannot go through the probe/search/font path above.

/** A check that reads a property of the paragraph rather than of a range. */
interface ParagraphCheck {
  readonly id: string;
  readonly title: string;
  readonly category: Category;
  readonly severity: Finding["severity"];
  /** The span the finding points at, or null when the paragraph is not in scope. */
  readonly anchor: (text: string) => { readonly start: number; readonly text: string } | null;
  /** Paragraph properties to load. */
  readonly load: string;
  readonly verdict: (paragraph: Word.Paragraph) => string | null;
  readonly fix: (paragraph: Word.Paragraph) => void;
}

/** Office.js spells the enum in TitleCase; compare loosely so a fake can too. */
function isCentered(alignment: unknown): boolean {
  return typeof alignment === "string" && alignment.toLowerCase() === "centered";
}

const PARAGRAPH_CHECKS: readonly ParagraphCheck[] = [
  {
    id: "caption-alignment",
    category: "figure",
    title: "キャプションは中央揃えにしない",
    severity: "fix",
    anchor: (text) => {
      const caption = parseCaption(text);
      return caption === null ? null : { start: caption.headStart, text: caption.head };
    },
    load: "alignment",
    verdict: (paragraph) =>
      isCentered(paragraph.alignment)
        ? "キャプションが中央揃えです。図の左端に合わせます（左揃え）。"
        : null,
    fix: (paragraph) => {
      paragraph.alignment = "Left" as Word.Alignment;
    },
  },
];

/** The formatting checks as data, for the rule list in 「ルール設定」. */
export const FORMAT_CHECK_INFO: ReadonlyArray<{
  readonly id: string;
  readonly title: string;
  readonly category: Category;
}> = [...CHECKS, ...PARAGRAPH_CHECKS].map(({ id, title, category }) => ({ id, title, category }));

/**
 * Checks that stay silent because a stronger, enabled check already covers them.
 *
 * Exported so that "this rule is on but reports nothing" is explainable rather
 * than mysterious — the rule list says so, and a test holds the pairing.
 */
export function supersededFormatChecks(disabled: ReadonlySet<string>): string[] {
  return CHECKS.filter((c) => c.supersededBy !== undefined && !disabled.has(c.supersededBy)).map(
    (c) => c.id,
  );
}

function activeChecks(disabled: ReadonlySet<string>): FormatCheck[] {
  const superseded = new Set(supersededFormatChecks(disabled));
  return CHECKS.filter((c) => !disabled.has(c.id) && !superseded.has(c.id));
}

/** Applies the fix belonging to a formatting finding. */
export function applyFormatFix(ruleId: string, font: Word.Font, latinFont: string): boolean {
  const check = CHECKS.find((c) => c.id === ruleId);
  if (!check?.fix) return false;
  check.fix(font, latinFont);
  return true;
}

export function isFormatCheckId(ruleId: string): boolean {
  return CHECKS.some((c) => c.id === ruleId);
}

export function isParagraphCheckId(ruleId: string): boolean {
  return PARAGRAPH_CHECKS.some((c) => c.id === ruleId);
}

/** Applies the fix belonging to a paragraph-level finding. */
export function applyParagraphFix(ruleId: string, paragraph: Word.Paragraph): boolean {
  const check = PARAGRAPH_CHECKS.find((c) => c.id === ruleId);
  if (!check) return false;
  check.fix(paragraph);
  return true;
}

/**
 * Runs the paragraph-level checks. One `context.sync()` for the whole document:
 * every paragraph in scope has its properties requested before the first wait.
 */
export async function runParagraphChecks(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
  paragraphTexts: readonly string[],
  disabled: ReadonlySet<string> = new Set(),
): Promise<Finding[]> {
  interface Pending {
    readonly check: ParagraphCheck;
    readonly paragraph: Word.Paragraph;
    readonly paragraphIndex: number;
    readonly anchor: { readonly start: number; readonly text: string };
  }

  const checks = PARAGRAPH_CHECKS.filter((c) => !disabled.has(c.id));
  if (checks.length === 0) return [];

  const pending: Pending[] = [];
  paragraphTexts.forEach((text, paragraphIndex) => {
    const paragraph = paragraphs[paragraphIndex];
    if (!paragraph) return;
    for (const check of checks) {
      const anchor = check.anchor(text);
      if (!anchor) continue;
      paragraph.load(check.load);
      pending.push({ check, paragraph, paragraphIndex, anchor });
    }
  });

  if (pending.length === 0) return [];
  await context.sync();

  const findings: Finding[] = [];
  for (const item of pending) {
    const message = item.check.verdict(item.paragraph);
    if (!message) continue;
    findings.push({
      ruleId: item.check.id,
      category: item.check.category,
      severity: item.check.severity,
      paragraphIndex: item.paragraphIndex,
      start: item.anchor.start,
      end: item.anchor.start + item.anchor.text.length,
      matched: item.anchor.text,
      message,
    });
  }
  return findings;
}

/**
 * Runs every formatting check over the given paragraphs.
 *
 * All probes across all checks are searched in one batch, then all fonts are
 * loaded in a second batch, so the whole pass costs two `context.sync()` calls
 * regardless of how many findings there are.
 */
export async function runFormatChecks(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
  paragraphTexts: readonly string[],
  disabled: ReadonlySet<string> = new Set(),
): Promise<Finding[]> {
  interface Pending {
    readonly check: FormatCheck;
    readonly probe: Probe;
    readonly paragraphIndex: number;
    readonly ordinal: number;
    readonly results: Word.RangeCollection;
  }

  const pending: Pending[] = [];
  const checks = activeChecks(disabled);

  paragraphTexts.forEach((text, paragraphIndex) => {
    const paragraph = paragraphs[paragraphIndex];
    if (!paragraph) return;
    for (const check of checks) {
      for (const probe of check.probe(text)) {
        const term = searchTermFor(probe.text);
        if (term.length === 0) continue;
        const ordinal = occurrenceIndex(text, probe.text, probe.start);
        if (ordinal < 0) continue;
        const results = paragraph.search(term, EXACT);
        results.load("items");
        pending.push({ check, probe, paragraphIndex, ordinal, results });
      }
    }
  });

  if (pending.length === 0) return [];
  await context.sync();

  const resolved: Array<{ pending: Pending; range: Word.Range }> = [];
  for (const item of pending) {
    const range = item.results.items[item.ordinal];
    if (!range) continue;
    range.font.load(item.check.load);
    resolved.push({ pending: item, range });
  }

  if (resolved.length === 0) return [];
  await context.sync();

  const findings: Finding[] = [];
  for (const { pending: item, range } of resolved) {
    const message = item.check.verdict(range.font, item.probe);
    if (!message) continue;
    const replacement = item.check.replacement?.(item.probe);
    findings.push({
      ruleId: item.check.id,
      category: item.check.category,
      severity: item.check.severity,
      paragraphIndex: item.paragraphIndex,
      start: item.probe.start,
      end: item.probe.end,
      matched: item.probe.text,
      ...(replacement === undefined ? {} : { replacement }),
      message,
    });
  }
  return findings;
}

/**
 * 上付きの数字は引用番号なので、和文との間に空白は要らない.
 *
 * 「である14，」 is a citation and 「その14件」 is the number fourteen; the text is the
 * same shape and only the formatting tells them apart. So 「和文と英数字の間隔」
 * reports both, and this pass — the only place that can see superscripts — takes
 * the citations back out.
 *
 * Only findings that touch digits are looked up, so a document with no citation
 * numbers costs nothing beyond the check for them.
 */
export async function dropSuperscriptCitations(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
  paragraphTexts: readonly string[],
  findings: readonly Finding[],
): Promise<Finding[]> {
  interface Pending {
    readonly finding: Finding;
    readonly ordinal: number;
    readonly results: Word.RangeCollection;
  }

  const pending: Pending[] = [];
  for (const item of findings) {
    if (item.ruleId !== SPACING_RULE_ID) continue;
    const text = paragraphTexts[item.paragraphIndex];
    const paragraph = paragraphs[item.paragraphIndex];
    if (text === undefined || !paragraph) continue;

    const digits = digitRunFor(text, item);
    if (!digits) continue;
    const term = searchTermFor(digits.text);
    if (term.length === 0) continue;
    const ordinal = occurrenceIndex(text, digits.text, digits.start);
    if (ordinal < 0) continue;

    const results = paragraph.search(term, EXACT);
    results.load("items");
    pending.push({ finding: item, ordinal, results });
  }

  if (pending.length === 0) return [...findings];
  await context.sync();

  const resolved: Array<{ finding: Finding; range: Word.Range }> = [];
  for (const item of pending) {
    const range = item.results.items[item.ordinal];
    if (!range) continue;
    range.font.load("superscript");
    resolved.push({ finding: item.finding, range });
  }

  if (resolved.length === 0) return [...findings];
  await context.sync();

  const citations = new Set<Finding>();
  for (const { finding: item, range } of resolved) {
    if (range.font.superscript) citations.add(item);
  }
  return findings.filter((item) => !citations.has(item));
}

/**
 * 日英フォントの不一致 — reported as a document-wide inventory rather than per
 * character. Office.js exposes a single `font.name` per range, not the separate
 * ascii/eastAsia pair that DOCX stores, so the honest thing this layer can do is
 * show which fonts carry Japanese and which carry Latin, and flag pairings the
 * checklist calls wrong.
 */
export interface FontInventoryEntry {
  readonly font: string;
  readonly paragraphs: number;
  readonly sample: string;
}

export interface FontInventory {
  readonly entries: readonly FontInventoryEntry[];
  readonly mismatches: readonly string[];
}

export async function buildFontInventory(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
  paragraphTexts: readonly string[],
): Promise<FontInventory> {
  for (const paragraph of paragraphs) paragraph.font.load("name");
  await context.sync();

  const counts = new Map<string, { paragraphs: number; sample: string }>();
  paragraphs.forEach((paragraph, i) => {
    const name = paragraph.font.name;
    // A paragraph mixing fonts reports an empty name; nothing useful to say.
    if (!name) return;
    const existing = counts.get(name);
    if (existing) {
      existing.paragraphs += 1;
    } else {
      counts.set(name, { paragraphs: 1, sample: (paragraphTexts[i] ?? "").slice(0, 24) });
    }
  });

  const entries = [...counts.entries()]
    .map(([font, info]) => ({ font, ...info }))
    .sort((a, b) => b.paragraphs - a.paragraphs);

  const japanese = entries.filter((e) => isJapaneseFontName(e.font));
  const latin = entries.filter((e) => !isJapaneseFontName(e.font));

  const mismatches: string[] = [];
  for (const jp of japanese) {
    for (const en of latin) {
      const problem = latinFontMismatch(jp.font, en.font);
      if (!problem) continue;
      mismatches.push(
        `和文「${jp.font}」と欧文「${en.font}」の組み合わせ：${problem.reason}。期待されるのは ${problem.expected}。`,
      );
    }
  }
  if (japanese.length > 1) {
    mismatches.push(`和文フォントが ${japanese.length} 種類使われています：${japanese.map((e) => e.font).join("、")}`);
  }
  if (latin.length > 1) {
    mismatches.push(`欧文フォントが ${latin.length} 種類使われています：${latin.map((e) => e.font).join("、")}`);
  }

  return { entries, mismatches };
}

export { preferredLatinFont };
