/* global Office, document, HTMLInputElement, HTMLElement, location */
/**
 * The pane↔dialog link, shared by 「ルール設定」 and 「設定」.
 *
 * Both windows run as Office dialogs: their own window, and their own JavaScript
 * runtime separate from the task pane. They cannot touch the pane's variables,
 * so the current settings arrive in the URL fragment and the edited ones go back
 * through `messageParent`.
 *
 * The fragment is used rather than storage because the dialog is a different
 * runtime: if its `localStorage` turned out not to be the pane's, the window
 * would open showing defaults and then save those over the real settings.
 */
import { DEFAULT_PREFERENCES, loadPreferences, normalize, savePreferences, type Preferences } from "../taskpane/prefs.ts";

let prefs: Preferences = DEFAULT_PREFERENCES;

/** Reads the settings the pane handed over, falling back to this runtime's storage. */
export function seedPreferences(): Preferences {
  const seed = decodeURIComponent(location.hash.replace(/^#/u, ""));
  if (seed === "") {
    prefs = loadPreferences();
    return prefs;
  }
  try {
    prefs = normalize(JSON.parse(seed));
  } catch {
    prefs = loadPreferences();
  }
  return prefs;
}

export function preferences(): Preferences {
  return prefs;
}

/**
 * Applies a change and reports it to the pane.
 *
 * Every edit is sent immediately, so closing the window with its own [×] rather
 * than the button still keeps the settings.
 */
export function updatePreferences(patch: Partial<Preferences>): Preferences {
  prefs = { ...prefs, ...patch };
  send(false);
  return prefs;
}

/**
 * Reports the settings back to the pane. Also written to this runtime's storage,
 * which is the pane's own storage when the host shares it — harmless when not,
 * because the pane saves whatever it receives here.
 */
export function send(close: boolean): void {
  savePreferences(prefs);
  try {
    Office.context.ui.messageParent(JSON.stringify({ prefs, close }));
  } catch {
    // Message too large or messaging unavailable: the pane re-reads storage
    // when the window closes, so the settings are not lost.
  }
}

// --- DOM helpers ---------------------------------------------------------

export function byId(id: string): HTMLElement {
  const element = document.getElementById(id);
  if (!element) throw new Error(`missing element #${id}`);
  return element;
}

export function input(id: string): HTMLInputElement {
  return byId(id) as HTMLInputElement;
}

/**
 * Wires a row of tabs to the panels they show.
 *
 * Tabs exist because these windows are tall and narrow: a single scrolling
 * column made the user hunt for the setting they wanted.
 */
export function tabs(bar: HTMLElement, panels: readonly { id: string; label: string; body: HTMLElement }[]): void {
  const buttons: HTMLElement[] = [];
  const select = (index: number): void => {
    panels.forEach((panel, i) => {
      panel.body.hidden = i !== index;
      buttons[i]!.classList.toggle("selected", i === index);
      buttons[i]!.setAttribute("aria-selected", String(i === index));
    });
  };

  bar.innerHTML = "";
  bar.setAttribute("role", "tablist");
  panels.forEach((panel, index) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "tab";
    button.id = `tab-${panel.id}`;
    button.setAttribute("role", "tab");
    button.textContent = panel.label;
    button.onclick = () => select(index);
    bar.appendChild(button);
    buttons.push(button);
  });
  select(0);
}
