/**
 * Runs every rule over a document and returns a single ordered list of findings.
 *
 * The engine is the only place that knows the whole rule set, so the Office
 * layer never has to enumerate rules by hand.
 */
import { FORMAT_RULES } from "./rules/format.ts";
import { READABILITY_RULES } from "./rules/readability.ts";
import { SCIENCE_RULES } from "./rules/science.ts";
import { FIGURE_RULES } from "./rules/figure.ts";
import { REFERENCE_RULES } from "./rules/reference.ts";
import { cjkRatio } from "./text.ts";
import { compoundLabels } from "./labels.ts";
import type { Category, DocumentContext, Finding, Rule, RuleSettings } from "./types.ts";
import { DEFAULT_SETTINGS } from "./types.ts";

export const ALL_RULES: readonly Rule[] = Object.freeze([
  ...FORMAT_RULES,
  ...SCIENCE_RULES,
  ...READABILITY_RULES,
  ...FIGURE_RULES,
  ...REFERENCE_RULES,
]);

export interface ReviewOptions {
  readonly settings?: Partial<RuleSettings>;
  /** Rule ids to run. Omitted or empty means every rule. */
  readonly enabledRules?: readonly string[];
  /** Categories to run. Omitted or empty means every category. */
  readonly enabledCategories?: readonly Category[];
  /**
   * Rule ids the user has switched off in 「ルール設定」. Expressed as a deny list
   * rather than an allow list so that a rule added in a later version is on for
   * everyone who has saved settings.
   */
  readonly disabledRules?: readonly string[];
  /** Dictionary entries switched off individually, keyed by `entryKey()`. */
  readonly disabledEntries?: readonly string[];
}

/** Builds the shared context, resolving `documentLanguage: "auto"`. */
export function buildContext(
  paragraphs: readonly string[],
  settings: RuleSettings,
  disabledEntries: ReadonlySet<string> = new Set(),
): DocumentContext {
  const joined = paragraphs.join("\n");
  const isJapanese =
    settings.documentLanguage === "auto" ? cjkRatio(joined) > 0.1 : settings.documentLanguage === "ja";
  return { settings, isJapanese, disabledEntries, compoundLabels: compoundLabels(paragraphs) };
}

/**
 * Reviews a document given as an array of paragraph strings.
 *
 * Findings come back sorted by position so the task pane can list them in
 * reading order, with ties broken by rule id to keep the output stable between
 * runs on an unchanged document.
 */
export function review(paragraphs: readonly string[], options: ReviewOptions = {}): Finding[] {
  const settings: RuleSettings = { ...DEFAULT_SETTINGS, ...options.settings };
  const ctx = buildContext(paragraphs, settings, new Set(options.disabledEntries ?? []));

  const ruleFilter = new Set(options.enabledRules ?? []);
  const categoryFilter = new Set(options.enabledCategories ?? []);
  const disabled = new Set(options.disabledRules ?? []);
  const rules = ALL_RULES.filter(
    (rule) =>
      !disabled.has(rule.id) &&
      (ruleFilter.size === 0 || ruleFilter.has(rule.id)) &&
      (categoryFilter.size === 0 || categoryFilter.has(rule.category)),
  );

  const found: Finding[] = [];
  for (const rule of rules) {
    if (rule.kind === "document") {
      found.push(...rule.run(paragraphs, ctx));
    } else {
      paragraphs.forEach((text, index) => found.push(...rule.run(text, index, ctx)));
    }
  }

  return found.sort(
    (a, b) =>
      a.paragraphIndex - b.paragraphIndex ||
      a.start - b.start ||
      a.ruleId.localeCompare(b.ruleId),
  );
}

/** Groups findings by checklist category, preserving the sorted order. */
export function groupByCategory(findings: readonly Finding[]): Map<Category, Finding[]> {
  const groups = new Map<Category, Finding[]>();
  for (const item of findings) {
    if (!groups.has(item.category)) groups.set(item.category, []);
    groups.get(item.category)!.push(item);
  }
  return groups;
}

/** Groups findings by rule, for the "which check fired how often" summary. */
export function groupByRule(findings: readonly Finding[]): Map<string, Finding[]> {
  const groups = new Map<string, Finding[]>();
  for (const item of findings) {
    if (!groups.has(item.ruleId)) groups.set(item.ruleId, []);
    groups.get(item.ruleId)!.push(item);
  }
  return groups;
}

/** Looks up a rule's display title by id. */
export function ruleTitle(ruleId: string): string {
  return ALL_RULES.find((rule) => rule.id === ruleId)?.title ?? ruleId;
}

/**
 * Applies every `fix`-severity finding to a plain-text document. Used by the
 * unit tests and by the preview in the task pane; the real document is edited
 * through Word ranges so that formatting survives.
 */
export function applyFixes(paragraphs: readonly string[], findings: readonly Finding[]): string[] {
  const result = [...paragraphs];
  const byParagraph = new Map<number, Finding[]>();
  for (const item of findings) {
    if (item.replacement === undefined) continue;
    if (!byParagraph.has(item.paragraphIndex)) byParagraph.set(item.paragraphIndex, []);
    byParagraph.get(item.paragraphIndex)!.push(item);
  }

  for (const [index, items] of byParagraph) {
    // Right to left so earlier offsets stay valid, skipping any finding that
    // overlaps one already applied.
    const ordered = [...items].sort((a, b) => b.start - a.start);
    let text = result[index]!;
    let boundary = text.length;
    for (const item of ordered) {
      if (item.end > boundary) continue;
      if (text.slice(item.start, item.end) !== item.matched) continue;
      text = text.slice(0, item.start) + item.replacement + text.slice(item.end);
      boundary = item.start;
    }
    result[index] = text;
  }

  return result;
}
